CREATE OR REPLACE PACKAGE signups.validation AS
  TYPE t_signupform IS RECORD (
    name VARCHAR2(4000),
    email VARCHAR2(4000),
    age NUMBER
  );
  FUNCTION require_text(p_field IN VARCHAR2, p_value IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION require_email(p_value IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION require_age(p_value IN NUMBER) RETURN NUMBER;
  FUNCTION require_min_length(p_field IN VARCHAR2, p_value IN VARCHAR2, p_min_len IN NUMBER) RETURN VARCHAR2;
  FUNCTION require_max_length(p_field IN VARCHAR2, p_value IN VARCHAR2, p_max_len IN NUMBER) RETURN VARCHAR2;
  FUNCTION require_in_range(p_field IN VARCHAR2, p_value IN NUMBER, p_min IN NUMBER, p_max IN NUMBER) RETURN NUMBER;
  FUNCTION require_pattern(p_field IN VARCHAR2, p_value IN VARCHAR2, p_pattern IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION require_one_of(p_field IN VARCHAR2, p_value IN VARCHAR2, p_allowed IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION validate_signup(p_form IN t_signupform) RETURN t_signupform;
END validation;
